(function() {
  const container = document.getElementById("decade-chart");
  const width = container.clientWidth || 900;
  const height = 380;
  const margin = {top: 20, right: 30, bottom: 40, left: 60};
  const innerW = width - margin.left - margin.right;
  const innerH = height - margin.top - margin.bottom;

  const svg = d3.select(container).append("svg").attr("width", width).attr("height", height);
  const data = chartData.decades;
  const metrics = ['CAGR', 'Volatility', 'MaxDrawdown'];
  const colors = ['#0061f2', '#00c9a7', '#e74c3c'];

  const x0 = d3.scaleBand().domain(data.map(d => d.Decade)).range([0, innerW]).padding(0.2);
  const x1 = d3.scaleBand().domain(metrics).range([0, x0.bandwidth()]).padding(0.05);
  const y = d3.scaleLinear().domain([-90, 60]).range([innerH, 0]);

  const g = svg.append("g").attr("transform", `translate(${margin.left},${margin.top})`);

  g.append("g").attr("class", "grid").attr("transform", `translate(0,${innerH})`)
    .call(d3.axisBottom(x0).tickSize(-innerH).tickFormat(""));
  g.append("g").attr("class", "grid")
    .call(d3.axisLeft(y).tickSize(-innerW).tickFormat(""));

