  g.append("g").attr("class", "axis").attr("transform", `translate(0,${innerH})`)
    .call(d3.axisBottom(x0));
  g.append("g").attr("class", "axis")
    .call(d3.axisLeft(y).ticks(8, d => d + "%"));

  g.append("line").attr("x1", 0).attr("x2", innerW).attr("y1", y(0)).attr("y2", y(0))
    .attr("stroke", "#1a1a2e").attr("stroke-width", 1);

  g.append("text").attr("transform", "rotate(-90)").attr("y", -margin.left + 16)
    .attr("x", -innerH/2).attr("text-anchor", "middle").attr("fill", "#5a5a6e").attr("font-size", "12px")
    .text("Percentage (%)");

  const legend = d3.select(container).append("div").attr("class", "legend");
